+++ b/lockless_queue.h
@@ -0,0 +1,26 @@
+#ifndef LOCKLESS_QUEUE_H
+#define LOCKLESS_QUEUE_H
+#include <stdbool.h>
+#include <stddef.h>
+#include <stdint.h>
+#include <stdatomic.h>
+
+typedef struct lq_node {
+    struct lq_node *next;
+    int value;
+} lq_node_t;
+
+typedef struct {
+    lq_node_t *ptr;
+    uint64_t epoch;
+} lq_tagged_t;
+
+typedef struct {
+    _Atomic(lq_tagged_t) head;
+} lq_queue_t;
+
+void lq_init(lq_queue_t *q, lq_node_t *initial);
+void lq_push(lq_queue_t *q, lq_node_t *node);
+bool lq_pop(lq_queue_t *q, lq_node_t **out);
+
+#endif
--- /dev/null
+++ b/lockless_queue.c
@@ -0,0 +1,36 @@
+#include "lockless_queue.h"
+
+void lq_init(lq_queue_t *q, lq_node_t *initial) {
+    lq_tagged_t h = { .ptr = initial, .epoch = 0 };
+    atomic_store_explicit(&q->head, h, memory_order_release);
+}
+
+void lq_push(lq_queue_t *q, lq_node_t *node) {
+    lq_tagged_t old = atomic_load_explicit(&q->head, memory_order_acquire);
+    lq_tagged_t next;
+    do {
+        node->next = old.ptr;
+        /* Every successful head transition gets a new 64-bit generation. */
+        next = (lq_tagged_t){ .ptr = node, .epoch = old.epoch + 1 };
+    } while (!atomic_compare_exchange_weak_explicit(
+        &q->head, &old, next, memory_order_acq_rel, memory_order_acquire));
+}
+
+bool lq_pop(lq_queue_t *q, lq_node_t **out) {
+    lq_tagged_t old = atomic_load_explicit(&q->head, memory_order_acquire);
+    for (;;) {
+        if (old.ptr == NULL)
+            return false;
+        lq_tagged_t next = {
+            .ptr = old.ptr->next,
+            .epoch = old.epoch + 1
+        };
+        if (atomic_compare_exchange_weak_explicit(
+                &q->head, &old, next,
+                memory_order_acq_rel, memory_order_acquire)) {
+            *out = old.ptr;
+            return true;
+        }
+        /* CAS failure reloads old, including its current epoch. */
+    }
+}
--- /dev/null
+++ b/frontier_gh_0001_test.c
@@ -0,0 +1,40 @@
+#include "lockless_queue.h"
+#include <assert.h>
+#include <stdio.h>
+#include <string.h>
+
+int main(void) {
+    lq_node_t a = {.value = 11}, b = {.value = 22}, c = {.value = 33}, *out = NULL;
+    lq_queue_t q;
+    lq_init(&q, &a);
+    a.next = &b; b.next = NULL;
+
+    /* Deterministic A -> B -> A address recycle. */
+    lq_tagged_t stale = atomic_load_explicit(&q.head, memory_order_acquire);
+    assert(stale.ptr == &a && stale.epoch == 0);
+    assert(lq_pop(&q, &out) && out == &a);       /* head B, epoch 1 */
+    lq_push(&q, &a);                             /* head A, epoch 2 */
+    lq_tagged_t now = atomic_load_explicit(&q.head, memory_order_acquire);
+    assert(now.ptr == stale.ptr && now.epoch == 2);
+
+    /* Pointer-only CAS accepts the stale ABA state: reproduce the old bug. */
+    _Atomic(lq_node_t *) legacy = &a;
+    lq_node_t *legacy_stale = &a;
+    assert(atomic_compare_exchange_strong(&legacy, &legacy_stale, &b));
+
+    /* Tagged CAS rejects exactly that stale state. */
+    lq_tagged_t desired = {.ptr = &c, .epoch = 1};
+    bool swapped = atomic_compare_exchange_strong_explicit(
+        &q.head, &stale, desired, memory_order_acq_rel, memory_order_acquire);
+    assert(!swapped);
+    assert(stale.ptr == &a && stale.epoch == 2);
+
+    /* Baseline: rejected CAS did not mutate the stack; normal LIFO still works. */
+    assert(lq_pop(&q, &out) && out == &a);
+    assert(lq_pop(&q, &out) && out == &b);
+    assert(!lq_pop(&q, &out));
+    lq_push(&q, &c);
+    assert(lq_pop(&q, &out) && out == &c && out->value == 33);
+    printf("PASS: legacy ABA reproduced; 128-bit ptr+64-bit-epoch CAS rejected stale generation; LIFO baseline passed\n");
+    return 0;
+}
