#define WORKERS 4
#define CONNECTIONS 240
struct counts { atomic_int wakeups, accepts, wouldblock, errors, workers_active; };
static void die(const char *s) { perror(s); _exit(90); }
static int listener(int port) {
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0), one = 1;
    if (fd < 0) die("socket");
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &one, sizeof(one))) die("SO_REUSEPORT");
    struct sockaddr_in a = {.sin_family=AF_INET,.sin_port=htons(port),.sin_addr.s_addr=htonl(INADDR_LOOPBACK)};
    if (bind(fd,(struct sockaddr*)&a,sizeof(a)) || listen(fd,128)) die("bind/listen");
    return fd;
}
static void worker(int port, int exclusive, struct counts *c, int shared_fd) {
    int fd=shared_fd>=0?shared_fd:listener(port), ep=epoll_create1(0); struct epoll_event ev={.events=EPOLLIN|(exclusive?EPOLLEXCLUSIVE:0),.data.fd=fd}, out[8];
    if(ep<0 || epoll_ctl(ep,EPOLL_CTL_ADD,fd,&ev)) die("epoll registration");
    atomic_fetch_add(&c->workers_active,1);
    for(;;) {
        int n=epoll_wait(ep,out,8,15000); if(n<0){if(errno==EINTR)continue;die("epoll_wait");}
        if(n==0) _exit(91);
        for(int i=0;i<n;i++) {
            atomic_fetch_add(&c->wakeups,1);
            int accepted_this_wakeup=0;
            for(;;) {
                int s=accept4(fd,0,0,SOCK_NONBLOCK);
                if(s>=0){accepted_this_wakeup++;atomic_fetch_add(&c->accepts,1); char b[16]; (void)read(s,b,sizeof(b)); close(s); continue;}
                if(errno==EAGAIN||errno==EWOULDBLOCK){if(!accepted_this_wakeup)atomic_fetch_add(&c->wouldblock,1);break;}
                if(errno==EINTR) continue;
                atomic_fetch_add(&c->errors,1);
                break;
            }
        }
    }
}
int main(int argc,char **argv) {
    int exclusive=argc>1&&!strcmp(argv[1],"exclusive");
    struct counts *c=mmap(0,sizeof(*c),PROT_READ|PROT_WRITE,MAP_SHARED|MAP_ANONYMOUS,-1,0); if(c==MAP_FAILED)die("mmap");
    int probe=listener(0); struct sockaddr_in a; socklen_t al=sizeof(a); if(getsockname(probe,(struct sockaddr*)&a,&al))die("getsockname"); int port=ntohs(a.sin_port); close(probe);
    int shared_fd=exclusive?-1:listener(port);
    pid_t pids[WORKERS]; for(int i=0;i<WORKERS;i++){pids[i]=fork();if(!pids[i])worker(port,exclusive,c,shared_fd);if(pids[i]<0)die("fork");}
    for(int i=0;i<100&&atomic_load(&c->workers_active)<WORKERS;i++){struct timespec t={0,10000000};nanosleep(&t,0);}
    for(int i=0;i<CONNECTIONS;i++) {
        int s=socket(AF_INET,SOCK_STREAM,0),one=1;setsockopt(s,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));
        a.sin_port=htons(port);a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);a.sin_family=AF_INET;
        if(connect(s,(struct sockaddr*)&a,sizeof(a))) die("connect");
        if(write(s,"x",1)!=1) die("write");
        close(s);
    }
    for(int i=0;i<500&&atomic_load(&c->accepts)<CONNECTIONS;i++){struct timespec t={0,10000000};nanosleep(&t,0);}
    for(int i=0;i<WORKERS;i++) kill(pids[i],SIGKILL);
    for(int i=0;i<WORKERS;i++) while(waitpid(pids[i],0,0)<0&&errno==EINTR){}
    int w=atomic_load(&c->wakeups),ac=atomic_load(&c->accepts),wb=atomic_load(&c->wouldblock),er=atomic_load(&c->errors);
    printf("MODE=%s CONNECTIONS=%d WAKEUPS=%d ACCEPTS=%d EWOULDBLOCK=%d ERRORS=%d\n",exclusive?"EPOLLEXCLUSIVE":"LEGACY",CONNECTIONS,w,ac,wb,er);
    if(ac!=CONNECTIONS||er)return 2;
    if(exclusive&&wb!=0){puts("FAIL: exclusive registration still produced spurious empty wakeups");return 3;}
    if(!exclusive&&wb==0){puts("FAIL: negative control did not expose thundering herd");return 4;}
    puts(exclusive?"EPOLL_EXCLUSIVE_PASS=YES":"LEGACY_HERD_REPRODUCED=YES");return 0;
}

/* lockless_queue.c */
// FRONTIER-GH-0017: native aarch64 tagged-pointer ABA regression model.
// This is not presented as an upstream CPython source patch.
#define _GNU_SOURCE
#include <assert.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct node {
    struct node *next;
    unsigned value;
} node_t;

typedef struct __attribute__((aligned(16))) {
    node_t *ptr;
    uint64_t epoch;
} tagged_head_t;

typedef struct {
    tagged_head_t head;
    pthread_mutex_t gate_lock;
    pthread_cond_t gate_cv;
    int armed;
    int release;
    int stale_cas_rejected;
    node_t *worker_result;
} aba_fixture_t;

// ARMv8 exclusive doubleword-pair load/store gives a real lock-free 128-bit
// CAS on Cortex-A72: pointer + full 64-bit epoch are one atomic primitive.
static inline tagged_head_t atomic_load_tagged(tagged_head_t *head) {
    uint64_t ptr, epoch;
    __asm__ volatile(
        "ldaxp %x0, %x1, %2\n\t"
        "clrex"
        : "=&r"(ptr), "=&r"(epoch), "+Q"(*head)
        :
        : "memory");
    tagged_head_t out = {(node_t *)(uintptr_t)ptr, epoch};
    return out;
}

extern int atomic_cas_tagged_asm(tagged_head_t *head,
                                 tagged_head_t *expected,
                                 const tagged_head_t *desired);

static inline bool atomic_cas_tagged(tagged_head_t *head,
                                     tagged_head_t *expected,
                                     tagged_head_t desired) {
    return atomic_cas_tagged_asm(head, expected, &desired) == 1;
}

static void tagged_push(tagged_head_t *head, node_t *n) {
    tagged_head_t old = atomic_load_tagged(head);
    for (;;) {
        tagged_head_t desired = {n, old.epoch + 1};
        n->next = old.ptr;
        if (atomic_cas_tagged(head, &old, desired)) return;
    }
}

static void aba_gate_wait(aba_fixture_t *f) {
    pthread_mutex_lock(&f->gate_lock);
    f->armed = 1;
    pthread_cond_broadcast(&f->gate_cv);
    while (!f->release) pthread_cond_wait(&f->gate_cv, &f->gate_lock);
    pthread_mutex_unlock(&f->gate_lock);
}

static node_t *tagged_pop_gated(aba_fixture_t *f, bool use_epoch) {
    tagged_head_t old = atomic_load_tagged(&f->head);
    for (;;) {
        if (!old.ptr) return NULL;
        node_t *next = old.ptr->next;
        aba_gate_wait(f);
        // Legacy ignores the epoch; fixed CAS compares pointer AND epoch and
        // increments the generation on every successful head mutation.
        tagged_head_t desired = {next, use_epoch ? old.epoch + 1 : old.epoch};
        tagged_head_t expected = old;
        if (!use_epoch) expected.epoch = atomic_load_tagged(&f->head).epoch;
        if (atomic_cas_tagged(&f->head, &expected, desired)) return old.ptr;
        if (use_epoch) f->stale_cas_rejected++;
        old = expected;
    }
}

static void *aba_worker(void *arg, bool use_epoch) {
    aba_fixture_t *f = arg;
    f->worker_result = tagged_pop_gated(f, use_epoch);
    return NULL;
}

static void *legacy_worker(void *arg) { return aba_worker(arg, false); }
static void *fixed_worker(void *arg) { return aba_worker(arg, true); }

static void release_aba_worker(aba_fixture_t *f, pthread_t thread) {
    pthread_mutex_lock(&f->gate_lock);
    while (!f->armed) pthread_cond_wait(&f->gate_cv, &f->gate_lock);
    pthread_mutex_unlock(&f->gate_lock);
    // Recycle A after removing A and B while the worker holds A,B.
    node_t *a = f->head.ptr;
    tagged_head_t h = atomic_load_tagged(&f->head);
    tagged_head_t d = {a->next, h.epoch + 1};
    assert(atomic_cas_tagged(&f->head, &h, d));
    node_t *b = f->head.ptr;
    h = atomic_load_tagged(&f->head);
    d = (tagged_head_t){b->next, h.epoch + 1};
    assert(atomic_cas_tagged(&f->head, &h, d));
    tagged_push(&f->head, a);
    pthread_mutex_lock(&f->gate_lock);
    f->release = 1;
    pthread_cond_broadcast(&f->gate_cv);
    pthread_mutex_unlock(&f->gate_lock);
    pthread_join(thread, NULL);
    (void)b;
}

static int run_aba(bool fixed) {
    node_t a = {0}, b = {0};
    aba_fixture_t f;
    memset(&f, 0, sizeof(f));
    pthread_mutex_init(&f.gate_lock, NULL);
    pthread_cond_init(&f.gate_cv, NULL);
    tagged_push(&f.head, &b);
    tagged_push(&f.head, &a);
    pthread_t thread;
    assert(!pthread_create(&thread, NULL, fixed ? fixed_worker : legacy_worker, &f));
    release_aba_worker(&f, thread);
    bool legacy_aba = !fixed && f.worker_result == &a && f.head.ptr == &b;
    bool fixed_safe = fixed && f.worker_result == &a && f.head.ptr == NULL &&
                      f.stale_cas_rejected >= 1;
    printf("mode=%s worker=%s head=%s stale_cas_rejected=%d\n",
           fixed ? "fixed" : "legacy", f.worker_result == &a ? "A" : "other",
           f.head.ptr == &b ? "B(dangling)" : f.head.ptr == NULL ? "NULL" : "other",
           f.stale_cas_rejected);
    pthread_cond_destroy(&f.gate_cv);
    pthread_mutex_destroy(&f.gate_lock);
    if (fixed) {
        printf("TAGGED_EPOCH_ABA_REJECTED=%s\n", fixed_safe ? "YES" : "NO");
        return fixed_safe ? 0 : 2;
    }
    printf("LEGACY_ABA_REPRODUCED=%s\n", legacy_aba ? "YES" : "NO");
    return legacy_aba ? 0 : 3;
}

#define PRODUCERS 4
#define PER_PRODUCER 10000
#define TOTAL (PRODUCERS * PER_PRODUCER)
static tagged_head_t stress_head;
static node_t stress_nodes[TOTAL];
static atomic_uchar seen[TOTAL];
static atomic_int consumed;

static void *producer(void *arg) {
    unsigned p = (unsigned)(uintptr_t)arg;
    for (unsigned i = 0; i < PER_PRODUCER; i++) {
        unsigned id = p * PER_PRODUCER + i;
        stress_nodes[id].value = id;
        tagged_push(&stress_head, &stress_nodes[id]);
    }
    return NULL;
}

static void *consumer(void *arg) {
    (void)arg;
    for (;;) {
        tagged_head_t old = atomic_load_tagged(&stress_head);
        if (!old.ptr) {
            if (atomic_load_explicit(&consumed, memory_order_relaxed) == TOTAL) return NULL;
            sched_yield();
            continue;
        }
        tagged_head_t desired = {old.ptr->next, old.epoch + 1};
        if (!atomic_cas_tagged(&stress_head, &old, desired)) continue;
        unsigned id = old.ptr->value;
        if (id >= TOTAL || atomic_exchange_explicit(&seen[id], 1, memory_order_relaxed)) {
            fprintf(stderr, "duplicate/corrupt node id=%u\n", id);
            abort();
        }
        atomic_fetch_add_explicit(&consumed, 1, memory_order_relaxed);
    }
}

static int run_stress(void) {
    pthread_t producers[PRODUCERS], consumers[PRODUCERS];
    for (uintptr_t i = 0; i < PRODUCERS; i++)
        assert(!pthread_create(&producers[i], NULL, producer, (void *)i));
    for (unsigned i = 0; i < PRODUCERS; i++)
        assert(!pthread_create(&consumers[i], NULL, consumer, NULL));
    for (unsigned i = 0; i < PRODUCERS; i++) pthread_join(producers[i], NULL);
    for (unsigned i = 0; i < PRODUCERS; i++) pthread_join(consumers[i], NULL);
    int count = atomic_load(&consumed);
    bool pass = count == TOTAL && stress_head.ptr == NULL;
    for (unsigned i = 0; i < TOTAL; i++) pass &= atomic_load(&seen[i]) == 1;
    printf("stress_produced=%d stress_consumed=%d final_epoch=%llu duplicates=0\n",
           TOTAL, count, (unsigned long long)stress_head.epoch);
    printf("TAGGED_STRESS_PASS=%s\n", pass ? "YES" : "NO");
    return pass ? 0 : 4;
}

int main(int argc, char **argv) {
    const char *mode = argc > 1 ? argv[1] : "all";
    if (!strcmp(mode, "legacy")) return run_aba(false);
    if (!strcmp(mode, "fixed")) {
        int rc = run_aba(true);
        if (rc) return rc;
        return run_stress();
    }
    if (!strcmp(mode, "all")) {
        int a = run_aba(false), b = run_aba(true), c = b ? b : run_stress();
        return a || b || c;
    }
    fprintf(stderr, "usage: %s [legacy|fixed|all]\n", argv[0]);
    return 64;
}

/* tagged_cas_aarch64.S */
// Real ARMv8 128-bit tagged-head CAS: pointer + 64-bit epoch.
// bool atomic_cas_tagged_asm(head=x0, expected=x1, desired=x2)
// expected is refreshed on comparison failure, matching C11 CAS semantics.
.text
.align 2
.global atomic_cas_tagged_asm
.type atomic_cas_tagged_asm, %function
atomic_cas_tagged_asm:
    mov     x9, x0
    ldp     x3, x4, [x1]
    ldp     x5, x6, [x2]
1:
    ldaxp   x7, x8, [x9]
    cmp     x7, x3
    ccmp    x8, x4, #0, eq
    b.ne    3f
    stlxp   w10, x5, x6, [x9]
    cbnz    w10, 1b
    mov     w0, #1
    ret
3:
    stp     x7, x8, [x1]
    clrex
    mov     w0, #0
    ret
.size atomic_cas_tagged_asm, .-atomic_cas_tagged_asm
.section .note.GNU-stack,"",@progbits

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TICKS 256
#define BUDGET 64
#define GLOBAL_TASKS 4

typedef enum { READY, PENDING } poll_result;

typedef struct {
    int id;
    int completed;
} task;

/* An unyielding cooperative future: every poll returns PENDING and the
 * scheduler immediately requeues it at the local queue's tail. */
static poll_result unyielding_local_poll(task *t) {
    (void)t;
    return PENDING;
}

static poll_result global_poll(task *t) {
    t->completed = 1;
    return READY;
}

typedef struct {
    unsigned local_polls;
    unsigned global_completed;
    unsigned fallback_checks;
    unsigned max_global_wait;
    unsigned final_budget;
} metrics;

static metrics run_scheduler(int fixed) {
    task local = {.id = 1, .completed = 0};
    task global[GLOBAL_TASKS];
    for (int i = 0; i < GLOBAL_TASKS; i++) {
        global[i].id = 100 + i;
        global[i].completed = 0;
    }

    metrics m = {0};
    unsigned global_head = 0;
    unsigned ticks_since_global = 0;
    unsigned budget = BUDGET;

    for (unsigned tick = 1; tick <= TICKS; tick++) {
        if (global_head < GLOBAL_TASKS) ticks_since_global++;
        if (ticks_since_global > m.max_global_wait)
            m.max_global_wait = ticks_since_global;

        /* The repaired worker checks its global queue every 64 local polls,
         * including when the local unyielding future keeps winning polls. */
        int global_fallback_due = fixed && ticks_since_global >= BUDGET;
        if (global_fallback_due && global_head < GLOBAL_TASKS) {
            m.fallback_checks++;
            if (global_poll(&global[global_head]) == READY) {
                global_head++;
                m.global_completed++;
            }
            ticks_since_global = 0;
            budget = BUDGET;
            continue;
        }

        /* Legacy behavior: nonempty local queue always wins and the global
         * queue is never examined. Fixed behavior decrements cooperative
         * budget on every local poll, including PENDING nested yields. */
        if (unyielding_local_poll(&local) == PENDING) {
            m.local_polls++;
            if (fixed) {
                if (budget == 0) {
                    fprintf(stderr, "budget underflow before fallback\n");
                    exit(2);
                }
                budget--;
            }
        }
    }
    m.final_budget = budget;
    return m;
}

int main(int argc, char **argv) {
    if (argc != 2 || (strcmp(argv[1], "legacy") && strcmp(argv[1], "fixed"))) {
        fprintf(stderr, "usage: %s legacy|fixed\n", argv[0]);
        return 2;
    }
    int fixed = !strcmp(argv[1], "fixed");
    metrics m = run_scheduler(fixed);
    printf("mode=%s ticks=%d local_polls=%u global_completed=%u "
           "global_starved=%u fallback_checks=%u max_global_wait_ticks=%u "
           "budget=%u invariant=%s\n",
           fixed ? "fixed" : "legacy", TICKS, m.local_polls,
           m.global_completed, m.global_completed == 0, m.fallback_checks,
           m.max_global_wait, m.final_budget,
           fixed && m.global_completed == GLOBAL_TASKS &&
                   m.max_global_wait == BUDGET && m.fallback_checks == GLOBAL_TASKS
               ? "PASS"
               : (!fixed && m.global_completed == 0 ? "STARVATION_REPRODUCED" : "FAIL"));
    if (!fixed)
        return m.global_completed == 0 && m.local_polls == TICKS ? 0 : 1;
    return m.global_completed == GLOBAL_TASKS && m.local_polls == TICKS - GLOBAL_TASKS &&
                   m.max_global_wait == BUDGET && m.fallback_checks == GLOBAL_TASKS &&
                   m.final_budget == BUDGET
               ? 0
               : 1;
}

#define _GNU_SOURCE
#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>

typedef struct {
    atomic_int refcount;
    int id;
} tstate;

typedef struct {
    tstate *thread;
    int id;
} interpreter_state;

static interpreter_state *global_interpreter;
static pthread_mutex_t head_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_barrier_t observed;
static pthread_barrier_t deletion_released;
static int fixed_mode;
static atomic_int final_refcount = -1;
static int freed_once;

static void *daemon_save_thread(void *unused) {
    (void)unused;
    interpreter_state *victim;
    tstate *ts;

    if (fixed_mode) {
        /* Fixed PyEval_SaveThread path: head_mutex protects the interpreter
         * list lookup and an atomic reference is acquired before unlock. */
        pthread_mutex_lock(&head_mutex);
        victim = global_interpreter;
        if (!victim) {
            fprintf(stderr, "fixed daemon found no interpreter\n");
            exit(2);
        }
        ts = victim->thread;
        atomic_fetch_add_explicit(&ts->refcount, 1, memory_order_acq_rel);
        pthread_mutex_unlock(&head_mutex);
    } else {
        /* Legacy defect: borrowed tstate pointer escapes with neither the
         * list mutex nor an owning reference. */
        victim = global_interpreter;
        ts = victim->thread;
    }

    pthread_barrier_wait(&observed);
    pthread_barrier_wait(&deletion_released);

    int old = atomic_fetch_sub_explicit(&ts->refcount, 1, memory_order_acq_rel);
    atomic_store_explicit(&final_refcount, old - 1, memory_order_release);
    if (fixed_mode) {
        if (old != 1) {
            fprintf(stderr, "fixed final refcount was %d, expected 1\n", old);
            exit(2);
        }
        if (munmap(ts, 4096) != 0) return NULL;
        free(victim);
        freed_once++;
    }
    return NULL;
}

static int run_once(void) {
    global_interpreter = malloc(sizeof(*global_interpreter));
    if (!global_interpreter) return 2;
    global_interpreter->thread = mmap(NULL, 4096, PROT_READ | PROT_WRITE,
                                      MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (global_interpreter->thread == MAP_FAILED) return 2;
    global_interpreter->id = 43;
    global_interpreter->thread->id = 4301;
    atomic_init(&global_interpreter->thread->refcount, 1);
    atomic_store(&final_refcount, -1);
    freed_once = 0;

    pthread_t daemon;
    if (pthread_create(&daemon, NULL, daemon_save_thread, NULL)) return 2;

    pthread_barrier_wait(&observed);
    if (fixed_mode) {
        /* Fixed PyInterpreterState_Delete: serialized list detach followed
         * by atomic drop of the list's owning reference. */
        pthread_mutex_lock(&head_mutex);
        interpreter_state *victim = global_interpreter;
        global_interpreter = NULL;
        int old = atomic_fetch_sub_explicit(&victim->thread->refcount, 1,
                                            memory_order_acq_rel);
        pthread_mutex_unlock(&head_mutex);
        if (old != 2) {
            fprintf(stderr, "fixed delete refcount was %d, expected 2\n", old);
            return 2;
        }
        /* old==2 means the daemon still owns tstate; do not free here. */
    } else {
        interpreter_state *victim = global_interpreter;
        global_interpreter = NULL;
        /* Unmapping the tstate page makes the legacy daemon's next atomic
         * access a real, deterministic SIGSEGV rather than a simulated error. */
        munmap(victim->thread, 4096);
        free(victim);
    }
    pthread_barrier_wait(&deletion_released);
    pthread_join(daemon, NULL);

    if (fixed_mode) {
        printf("mode=fixed detach=head_mutex initial_refs=2 daemon_lease=1 "
               "final_refcount=%d freed_once=%d invariant=PASS\n",
               atomic_load(&final_refcount), freed_once);
        return atomic_load(&final_refcount) == 0 && freed_once == 1 ? 0 : 1;
    }
    printf("mode=legacy unexpectedly completed without UAF detection\n");
    return 1;
}

int main(int argc, char **argv) {
    if (argc != 2 || (strcmp(argv[1], "legacy") && strcmp(argv[1], "fixed"))) {
        fprintf(stderr, "usage: %s legacy|fixed\n", argv[0]);
        return 2;
    }
    fixed_mode = !strcmp(argv[1], "fixed");
    if (pthread_barrier_init(&observed, NULL, 2) ||
        pthread_barrier_init(&deletion_released, NULL, 2)) return 2;
    int rc = run_once();
    pthread_barrier_destroy(&observed);
    pthread_barrier_destroy(&deletion_released);
    return rc;
}

#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <unistd.h>

#define WORKERS 4
#define ROUNDS 100

typedef struct {
    int fd;
    _Atomic int wakeups;
    _Atomic int accepted;
    _Atomic int eagain;
    _Atomic int release_accept;
    _Atomic int done;
} round_state;

typedef struct {
    int epfd;
    round_state *volatile round;
} worker_arg;

static _Atomic int stop_workers;
static worker_arg args[WORKERS];

static void die(const char *what) { perror(what); exit(2); }

static void *worker(void *opaque) {
    worker_arg *a = opaque;
    while (!atomic_load_explicit(&stop_workers, memory_order_relaxed)) {
        struct epoll_event events[8];
        int n = epoll_wait(a->epfd, events, 8, 10);
        if (n < 0) { if (errno == EINTR) continue; die("epoll_wait"); }
        for (int i = 0; i < n; i++) {
            round_state *r = events[i].data.ptr;
            if (r == NULL || r != a->round) continue;
            atomic_fetch_add_explicit(&r->wakeups, 1, memory_order_release);
            while (!atomic_load_explicit(&r->release_accept, memory_order_acquire))
                ; /* Intentional test barrier: expose every spurious wakeup. */
            int c;
            do { c = accept4(r->fd, NULL, NULL, SOCK_NONBLOCK | SOCK_CLOEXEC); }
            while (c < 0 && errno == EINTR);
            if (c >= 0) {
                atomic_fetch_add_explicit(&r->accepted, 1, memory_order_release);
                close(c);
            } else if (errno == EAGAIN || errno == EWOULDBLOCK) {
                atomic_fetch_add_explicit(&r->eagain, 1, memory_order_release);
            } else { die("accept4"); }
            atomic_fetch_add_explicit(&r->done, 1, memory_order_release);
        }
    }
    return NULL;
}

static int make_listener(uint16_t *port) {
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK | SOCK_CLOEXEC, 0);
    if (fd < 0) die("socket");
    int one = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one)) < 0) die("SO_REUSEADDR");
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &one, sizeof(one)) < 0) die("SO_REUSEPORT");
    int got = 0; socklen_t gotlen = sizeof(got);
    if (getsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &got, &gotlen) < 0 || got != 1) {
        fprintf(stderr, "SO_REUSEPORT readback failed\n"); exit(2);
    }
    struct sockaddr_in addr = { .sin_family = AF_INET, .sin_addr.s_addr = htonl(INADDR_LOOPBACK), .sin_port = 0 };
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) die("bind");
    if (listen(fd, 128) < 0) die("listen");
    socklen_t alen = sizeof(addr);
    if (getsockname(fd, (struct sockaddr *)&addr, &alen) < 0) die("getsockname");
    *port = ntohs(addr.sin_port);
    return fd;
}

static void connect_one(uint16_t port) {
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
    if (fd < 0) die("client socket");
    struct sockaddr_in addr = { .sin_family = AF_INET, .sin_addr.s_addr = htonl(INADDR_LOOPBACK), .sin_port = htons(port) };
    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) die("connect");
    close(fd);
}

int main(int argc, char **argv) {
    if (argc != 2 || (strcmp(argv[1], "legacy") && strcmp(argv[1], "fixed"))) {
        fprintf(stderr, "usage: %s legacy|fixed\n", argv[0]); return 2;
    }
    int fixed = !strcmp(argv[1], "fixed");
    pthread_t threads[WORKERS];
    for (int i = 0; i < WORKERS; i++) {
        args[i].epfd = epoll_create1(EPOLL_CLOEXEC);
        if (args[i].epfd < 0) die("epoll_create1");
        if (pthread_create(&threads[i], NULL, worker, &args[i])) die("pthread_create");
    }
    unsigned long total_wake = 0, total_accept = 0, total_eagain = 0;
    for (int iteration = 0; iteration < ROUNDS; iteration++) {
        uint16_t port;
        round_state r = { .fd = make_listener(&port) };
        uint32_t flags = EPOLLIN | (fixed ? EPOLLEXCLUSIVE : 0);
        for (int i = 0; i < WORKERS; i++) {
            args[i].round = &r;
            struct epoll_event event = { .events = flags, .data.ptr = &r };
            if (epoll_ctl(args[i].epfd, EPOLL_CTL_ADD, r.fd, &event) < 0) die("epoll_ctl ADD");
        }
